void topologicalSort(Graph *graph) {
  int inDegree[MAX_NODES] = {0};
  Queue queue = createQueue();
  List order = createList();

  forEach (Edge edge in graph->edges) {
    inDegree[edge.to]++;
  }
  forEach (Vertex v in graph->vertices) {
    if (inDegree[v] == 0) enqueue(&queue, v);
  }

  while (!isEmpty(&queue)) {
    Vertex current = dequeue(&queue);
    append(&order, current);

    forEach (Vertex next in graph->adj[current]) {
      inDegree[next]--;
      if (inDegree[next] == 0) enqueue(&queue, next);
    }
  }
}
